WITH rl AS (SELECT id_imovel,geometria,data_extracao FROM `basedosdados.br_sfb_sicar.reserva_legal` WHERE data_extracao='2026-08-03' AND id_imovel IN ('PA-1506187-3F4B7241FA0D4F60B91CCE115953FD56','PA-1506187-48EDE9CDCF3947959921871671228876')), g AS (SELECT id_imovel,MAX(data_extracao) data_extracao,ST_UNION_AGG(geometria) geom FROM rl GROUP BY id_imovel), p AS (SELECT a.geom geom_a,b.geom geom_b,a.data_extracao data_extracao_a,b.data_extracao data_extracao_b FROM g a JOIN g b ON a.id_imovel='PA-1506187-3F4B7241FA0D4F60B91CCE115953FD56' AND b.id_imovel='PA-1506187-48EDE9CDCF3947959921871671228876') SELECT data_extracao_a,data_extracao_b,ROUND(ST_AREA(geom_a)/10000,6) area_rl_a_ha,ROUND(ST_AREA(geom_b)/10000,6) area_rl_b_ha,ROUND(ST_AREA(ST_INTERSECTION(geom_a,geom_b))/10000,6) area_intersecao_ha,ROUND(SAFE_DIVIDE(ST_AREA(ST_INTERSECTION(geom_a,geom_b)),ST_AREA(geom_a))*100,6) percentual_sobre_a,ROUND(SAFE_DIVIDE(ST_AREA(ST_INTERSECTION(geom_a,geom_b)),ST_AREA(geom_b))*100,6) percentual_sobre_b FROM p